namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public int MaxEnrollment { get; set; }
    public bool IsFeatured { get; set; }
    public int DepartmentId { get; set; }
    public Department Department { get; set; } = null!;
    public int InstructorId { get; set; }
    public Instructor Instructor { get; set; } = null!;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be in format XX000000 (2 letters followed by 6 digits).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }

    public string? Comments { get; set; }
}

namespace UniversityCourseCatalog.Services;

using UniversityCourseCatalog.Models;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    Department? GetDepartment(int id);
    IReadOnlyList<Course> GetCourses(string? searchTerm = null, int? departmentId = null);
    IReadOnlyList<Course> GetFeaturedCourses();
    Course? GetCourse(int id);
    IReadOnlyList<Course> GetCoursesByDepartment(int departmentId);
    void SubmitEnrollmentRequest(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, data structures, and the design of software and hardware systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Exploration of abstract structures, patterns, and quantitative reasoning across pure and applied domains." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Investigation of matter, energy, and the fundamental forces that govern the natural world." },
            new() { Id = 4, Name = "English", Code = "ENGL", Description = "Critical reading, analytical writing, and the study of literature across historical periods and cultures." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 peer-reviewed papers and holds three patents in natural language processing.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor of Computer Science", Bio = "Dr. Martinez focuses on software engineering and distributed systems. He spent ten years in industry at major tech companies before joining academia.", Email = "rmartinez@university.edu" },
            new() { Id = 3, Name = "Dr. Sarah Johnson", Title = "Professor of Mathematics", Bio = "Dr. Johnson is a leading researcher in combinatorics and graph theory. She has received the university's Distinguished Teaching Award twice.", Email = "sjohnson@university.edu" },
            new() { Id = 4, Name = "Dr. James Liu", Title = "Associate Professor of Mathematics", Bio = "Dr. Liu's research centers on applied mathematics and numerical analysis. He collaborates with engineering departments on computational modeling projects.", Email = "jliu@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Watson", Title = "Professor of Physics", Bio = "Dr. Watson is an experimental physicist whose research focuses on quantum optics. She leads the university's photonics laboratory.", Email = "ewatson@university.edu" },
            new() { Id = 6, Name = "Dr. Michael Brown", Title = "Associate Professor of Physics", Bio = "Dr. Brown studies astrophysics and cosmology. He has contributed to several NASA-funded research projects on dark matter detection.", Email = "mbrown@university.edu" },
            new() { Id = 7, Name = "Dr. Karen Davis", Title = "Professor of English", Bio = "Dr. Davis is a scholar of nineteenth-century American literature. Her book on transcendentalist poetry won the National Book Critics Circle Award.", Email = "kdavis@university.edu" },
            new() { Id = 8, Name = "Dr. Thomas Wilson", Title = "Associate Professor of English", Bio = "Dr. Wilson specializes in creative writing and modern fiction. He is the author of two novels and a collection of short stories.", Email = "twilson@university.edu" }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Code = "CS 101", Name = "Introduction to Computer Science", Description = "An introductory course covering fundamental concepts of computing, problem solving, and programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", Location = "Tech Hall 201", MaxEnrollment = 120, IsFeatured = true, DepartmentId = 1, InstructorId = 1 },
            new() { Id = 2, Code = "CS 201", Name = "Data Structures and Algorithms", Description = "Study of fundamental data structures including arrays, linked lists, trees, and graphs. Analysis of algorithm efficiency and common algorithmic paradigms such as divide-and-conquer and dynamic programming.", Credits = 4, Schedule = "TR 10:00–11:15 AM", Location = "Tech Hall 305", MaxEnrollment = 60, IsFeatured = true, DepartmentId = 1, InstructorId = 1 },
            new() { Id = 3, Code = "CS 310", Name = "Software Engineering", Description = "Principles and practices of software development including agile methodologies, version control, testing, and project management. Students work in teams on a semester-long project.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", Location = "Tech Hall 110", MaxEnrollment = 40, IsFeatured = false, DepartmentId = 1, InstructorId = 2 },
            new() { Id = 4, Code = "CS 450", Name = "Artificial Intelligence", Description = "Introduction to AI concepts including search algorithms, knowledge representation, machine learning fundamentals, and neural networks. Includes hands-on projects with real-world datasets.", Credits = 3, Schedule = "TR 2:30–3:45 PM", Location = "Tech Hall 402", MaxEnrollment = 35, IsFeatured = true, DepartmentId = 1, InstructorId = 1 },

            // Mathematics
            new() { Id = 5, Code = "MATH 101", Name = "Calculus I", Description = "Limits, continuity, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.", Credits = 4, Schedule = "MWF 10:00–10:50 AM", Location = "Science Center 101", MaxEnrollment = 150, IsFeatured = true, DepartmentId = 2, InstructorId = 3 },
            new() { Id = 6, Code = "MATH 201", Name = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Applications in data science and engineering.", Credits = 3, Schedule = "TR 1:00–2:15 PM", Location = "Science Center 203", MaxEnrollment = 45, IsFeatured = false, DepartmentId = 2, InstructorId = 4 },
            new() { Id = 7, Code = "MATH 301", Name = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis. Emphasizes real-world data analysis using statistical software.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", Location = "Science Center 105", MaxEnrollment = 50, IsFeatured = false, DepartmentId = 2, InstructorId = 3 },

            // Physics
            new() { Id = 8, Code = "PHYS 101", Name = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Covers Newton's laws, energy conservation, rotational dynamics, and oscillatory motion with calculus-based problem solving.", Credits = 4, Schedule = "MWF 9:00–9:50 AM", Location = "Physics Building 100", MaxEnrollment = 100, IsFeatured = true, DepartmentId = 3, InstructorId = 5 },
            new() { Id = 9, Code = "PHYS 201", Name = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves. Laboratory component includes experiments with circuits and optics.", Credits = 4, Schedule = "TR 10:00–11:15 AM", Location = "Physics Building 210", MaxEnrollment = 40, IsFeatured = false, DepartmentId = 3, InstructorId = 5 },
            new() { Id = 10, Code = "PHYS 350", Name = "Quantum Mechanics", Description = "Wave-particle duality, Schrödinger equation, quantum states, and measurement. Introduction to applications in modern technology.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", Location = "Physics Building 310", MaxEnrollment = 30, IsFeatured = false, DepartmentId = 3, InstructorId = 6 },

            // English
            new() { Id = 11, Code = "ENGL 101", Name = "College Writing", Description = "Development of critical reading, analytical writing, and argumentation skills. Students compose essays in multiple genres and learn research methods.", Credits = 3, Schedule = "MWF 10:00–10:50 AM", Location = "Humanities Hall 105", MaxEnrollment = 25, IsFeatured = false, DepartmentId = 4, InstructorId = 7 },
            new() { Id = 12, Code = "ENGL 220", Name = "American Literature", Description = "Survey of major American literary works from the colonial period to the present, exploring themes of identity, democracy, and social change.", Credits = 3, Schedule = "TR 1:00–2:15 PM", Location = "Humanities Hall 201", MaxEnrollment = 30, IsFeatured = true, DepartmentId = 4, InstructorId = 7 },
            new() { Id = 13, Code = "ENGL 315", Name = "Creative Writing Workshop", Description = "Workshop-based course in fiction and poetry writing. Students draft, revise, and critique original works in a supportive peer environment.", Credits = 3, Schedule = "TR 3:30–4:45 PM", Location = "Humanities Hall 110", MaxEnrollment = 18, IsFeatured = false, DepartmentId = 4, InstructorId = 8 }
        };

        // Link navigation properties
        foreach (var course in _courses)
        {
            course.Department = _departments.First(d => d.Id == course.DepartmentId);
            course.Instructor = _instructors.First(i => i.Id == course.InstructorId);
        }
    }

    public IReadOnlyList<Department> GetDepartments() => _departments.AsReadOnly();

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Name.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList().AsReadOnly();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList().AsReadOnly();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList().AsReadOnly();

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        _enrollmentRequests.Add(request);
    }
}

