arguments.file_text:
@page "/courses"
@inject ICatalogService CatalogService

<PageTitle>Course Catalog - University Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="search" class="form-label">Search by name or code</label>
        <input type="text" class="form-control" id="search" name="Search" value="@Search" placeholder="e.g. Calculus, CS 101" />
    </div>
    <div class="col-md-4">
        <label for="department" class="form-label">Department</label>
        <select class="form-select" id="department" name="DepartmentId">
            <option value="">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Search</button>
    </div>
</form>

@{
    var courses = CatalogService.GetCourses(Search, DepartmentId);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria. Try adjusting your search or filter.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Name</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <tr>
                        <td>@course.Code</td>
                        <td>@course.Name</td>
                        <td>@course.Department.Name</td>
                        <td>@course.Credits</td>
                        <td>@course.Schedule</td>
                        <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/enroll"
@inject ICatalogService CatalogService
@inject NavigationManager NavigationManager

<PageTitle>Enroll - University Course Catalog</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>
<p class="text-muted mb-4">Fill out the form below to submit an enrollment request.</p>

<div class="row">
    <div class="col-md-8 col-lg-6">
        <EditForm Model="Model" FormName="EnrollmentForm" OnValidSubmit="HandleSubmit" method="post">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger mb-3" />

            <div class="mb-3">
                <label for="studentName" class="form-label">Student Name</label>
                <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
                <ValidationMessage For="() => Model.StudentName" />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <InputText id="studentId" class="form-control" placeholder="e.g. AB123456" @bind-Value="Model.StudentId" />
                <ValidationMessage For="() => Model.StudentId" />
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course</label>
                <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                    <option value="0">-- Select a course --</option>
                    @foreach (var course in CatalogService.GetCourses())
                    {
                        <option value="@course.Id">@course.Code - @course.Name</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.CourseId" />
            </div>

            <div class="mb-3">
                <label for="comments" class="form-label">Comments (optional)</label>
                <InputTextArea id="comments" class="form-control" rows="3" @bind-Value="Model.Comments" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
        </EditForm>
    </div>
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollmentRequest(Model);
        NavigationManager.NavigateTo("/enroll/confirmation");
    }
}

